# Generated by scripts/update_formula.py from the release manifest; edit the script, not this file.
class JiraCliToolkit < Formula
  desc "Independent CLI for Jira Cloud issues, sprints and REST APIs"
  homepage "https://jira.abhishekaggarwal.com/"
  license "AGPL-3.0-only"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    depends_on macos: :sequoia

    on_arm do
      url "https://github.com/User17745/jira-cli-toolkit/releases/download/v2.5.2/jira-cli-toolkit-macos-arm64"
      sha256 "d830c1f1c4170e210575973e173b86b6b03f2bdc8968e856d243d3a0b9e3c73f"
    end
    on_intel do
      url "https://github.com/User17745/jira-cli-toolkit/releases/download/v2.5.2/jira-cli-toolkit-macos-x86_64"
      sha256 "0cddd5ea655faf68c0671bd782f15f971ea4199624e54b662d77f5ab4936eb30"
    end
  end

  on_linux do
    # Only an x86_64 Linux binary is published; ARM Linux is refused with this requirement.
    # Both blocks name the same file so the formula still loads on every platform.
    depends_on arch: :x86_64

    on_intel do
      url "https://github.com/User17745/jira-cli-toolkit/releases/download/v2.5.2/jira-cli-toolkit-linux-x86_64"
      sha256 "37093168bc86e9f2236ccdf9f0d1fcf2926e1320a0f4ae1a714dbf6e21311b0b"
    end
    on_arm do
      url "https://github.com/User17745/jira-cli-toolkit/releases/download/v2.5.2/jira-cli-toolkit-linux-x86_64"
      sha256 "37093168bc86e9f2236ccdf9f0d1fcf2926e1320a0f4ae1a714dbf6e21311b0b"
    end
  end

  def install
    # Each release asset is a single self-contained executable, installed as `jira`.
    bin.install Dir["jira-cli-toolkit-*"].fetch(0) => "jira"
  end

  test do
    assert_equal "jira #{version}", shell_output("#{bin}/jira --version").strip
    assert_match "usage: jira issue list", shell_output("#{bin}/jira help issue list")
    # Updates belong to Homebrew; the CLI must not replace its own Cellar files.
    if version >= Version.new("2.5.2")
      assert_match '"method": "homebrew"', shell_output("#{bin}/jira update --info --json")
    end
  end
end
